/** Kartu bernomor untuk poin utama: nomor besar di kiri, uraian ringkas di kanan. */
const points = (s: PptxGenJS.Slide, items: string[], x: number, y: number, w: number, h = 0.62, gap = 0.09) => {
    items.slice(0, 5).forEach((t, i) => {
        const yy = y + i * (h + gap);
        s.addShape(pptx.ShapeType.rect, { x, y: yy, w, h, fill: { color: i % 2 ? C.zebra : C.white }, line: { color: C.line, width: 1 } });
        s.addShape(pptx.ShapeType.rect, { x, y: yy, w: 0.08, h, fill: { color: C.blue }, line: { color: C.blue, width: 0 } });
        s.addText(String(i + 1).padStart(2, '0'), { x: x + 0.16, y: yy, w: 0.72, h, fontSize: 20, bold: true, color: C.blue, fontFace: FONT, align: 'center', valign: 'middle', margin: 0 });
        s.addText(t, { x: x + 0.98, y: yy, w: w - 1.15, h, fontSize: 13, color: C.text, fontFace: FONT, valign: 'middle', margin: 0, fit: 'shrink' });
    });
};

